    ('c06a9fcb-91e4-5a78-9d38-17ada25871b6'::uuid, 'Découverte du monde et rencontre des cultures'),
    ('bf7993d7-c076-572f-9825-54e86605b90a'::uuid, 'Découverte du monde et rencontre des cultures'),
