ON CONFLICT (id) DO NOTHING;

-- 4. Questions -------------------------------------------------------------
INSERT INTO public.quiz_questions (id, quiz_id, question, kind, options, correct_index, explanation, position)
SELECT v.id, v.quiz_id, v.question, v.kind, v.options, v.correct_index, v.explanation, v.position
  FROM (VALUES
    ('b31a8b82-a42d-5dd1-bbac-2674c2e5dab8'::uuid, '16e70776-633f-5af0-85a9-af4713019c32'::uuid, 'Dans quel contexte historique la rhétorique est-elle née ?', 'mcq', '["Dans la Sicile du Ve siècle avant notre ère, à l’occasion de procès","À Rome sous l’Empire","En France au XVIIe siècle","En Grèce à l’époque homérique"]'::jsonb, 0, 'Elle est d’emblée liée à la démocratie et au règlement des litiges par la parole.', 1),
    ('86275669-b9fc-52a0-8b61-9fa372e69987'::uuid, '16e70776-633f-5af0-85a9-af4713019c32'::uuid, 'Quel genre rhétorique porte sur l’avenir et vise l’utile ?', 'mcq', '["Le délibératif","Le judiciaire","L’épidictique","Le narratif"]'::jsonb, 0, 'C’est le genre de l’assemblée politique.', 2),
    ('2c3799cc-d260-5fa7-abd8-81caac0a03e0'::uuid, '16e70776-633f-5af0-85a9-af4713019c32'::uuid, 'Quelles sont les cinq parties de la rhétorique ?', 'mcq', '["Invention, disposition, élocution, mémoire, action","Exorde, narration, confirmation, péroraison, conclusion","Ethos, pathos, logos, mythos, kairos","Lire, écrire, parler, écouter, retenir"]'::jsonb, 0, 'Elles suivent l’ordre du travail de l’orateur.', 3),
    ('264a431a-83cb-5d68-8dc9-01ffc0356156'::uuid, '16e70776-633f-5af0-85a9-af4713019c32'::uuid, 'Que désigne l’ethos dans la persuasion ?', 'mcq', '["L’image que l’orateur donne de lui-même","L’émotion suscitée chez l’auditoire","Le raisonnement logique","Le sujet du discours"]'::jsonb, 0, 'Le pathos vise l’émotion, le logos le raisonnement.', 4),
    ('75871cfe-13b8-5fc5-9908-7ff723e433d0'::uuid, '16e70776-633f-5af0-85a9-af4713019c32'::uuid, 'Platon fait l’éloge de la rhétorique dans le Gorgias.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il en fait le PROCÈS : une flatterie qui néglige le vrai.', 5),
    ('5f15dbc1-b618-5fb9-8f81-360405a2b4c1'::uuid, '16e70776-633f-5af0-85a9-af4713019c32'::uuid, 'Comment Aristote défend-il la rhétorique ?', 'mcq', '["Comme une technique moralement neutre, qu’il vaut mieux connaître","Comme une science exacte","Comme un art réservé aux philosophes","Comme une forme de poésie"]'::jsonb, 0, 'L’ignorer laisserait le champ libre à ceux qui en usent mal.', 6),
    ('f8d09ff7-59a9-5506-8967-b2ebf1a2ed09'::uuid, '16e70776-633f-5af0-85a9-af4713019c32'::uuid, 'Que recouvre l’« action » dans les cinq parties de la rhétorique ?', 'mcq', '["La prononciation du discours : voix, regard, geste","Le fait d’agir après avoir parlé","La recherche des arguments","L’ordre des parties du discours"]'::jsonb, 0, 'Démosthène en faisait, dit-on, l’essentiel de l’éloquence.', 7),
    ('47c79d93-c948-5fc0-b0f4-7dcdeaac6c15'::uuid, '16e70776-633f-5af0-85a9-af4713019c32'::uuid, 'Quel genre rhétorique loue ou blâme au présent ?', 'mcq', '["L’épidictique","Le judiciaire","Le délibératif","Le polémique"]'::jsonb, 0, 'Il vise le beau, là où le judiciaire vise le juste.', 8),
    ('3a984220-a928-594f-b6b3-48959521bbe9'::uuid, '3c7d74cc-cacf-5dc7-b8b2-faceafc1cf8c'::uuid, 'Quelles sont les trois fonctions du discours selon la tradition latine ?', 'mcq', '["Instruire, plaire, émouvoir","Décrire, raconter, argumenter","Louer, blâmer, juger","Écouter, parler, écrire"]'::jsonb, 0, 'Docere, delectare, movere chez Cicéron.', 1),
    ('58d6bdcd-3b86-50fd-914b-e8c42aa99620'::uuid, '3c7d74cc-cacf-5dc7-b8b2-faceafc1cf8c'::uuid, 'Quelle est la différence entre convaincre et persuader ?', 'mcq', '["Convaincre s’adresse à la raison, persuader à la sensibilité","Convaincre s’adresse aux émotions, persuader à la logique","Ce sont des synonymes","Convaincre concerne l’écrit, persuader l’oral"]'::jsonb, 0, 'On peut être convaincu sans être persuadé, et l’inverse.', 2),
    ('b8e9efcb-0c37-52be-b6bd-c9378948c601'::uuid, '3c7d74cc-cacf-5dc7-b8b2-faceafc1cf8c'::uuid, 'Peut-on être persuadé sans être convaincu ?', 'mcq', '["Oui, et c’est précisément le danger","Non, jamais","Oui, mais uniquement à l’écrit","Non, les deux sont identiques"]'::jsonb, 0, 'L’adhésion emporte alors sans que la raison ait été satisfaite.', 3),
    ('5214ade4-5f83-5152-97fe-5764a38576c0'::uuid, '3c7d74cc-cacf-5dc7-b8b2-faceafc1cf8c'::uuid, 'À quelle famille appartient l’anaphore ?', 'mcq', '["Aux figures d’insistance","Aux figures d’analogie","Aux figures d’opposition","Aux figures d’atténuation"]'::jsonb, 0, 'Elle martèle en répétant un mot en tête de plusieurs segments.', 4),
    ('41f307fd-19e9-5739-bd00-99510786b2c9'::uuid, '3c7d74cc-cacf-5dc7-b8b2-faceafc1cf8c'::uuid, 'Qu’est-ce qu’une litote ?', 'mcq', '["Une figure qui dit moins pour suggérer plus","Une exagération volontaire","Une comparaison sans outil","Une opposition de deux termes"]'::jsonb, 0, 'Elle appartient aux figures d’atténuation, avec l’euphémisme.', 5),
    ('71576723-33fd-5927-990e-a4f99a39b03f'::uuid, '3c7d74cc-cacf-5dc7-b8b2-faceafc1cf8c'::uuid, 'Un discours entièrement écrit dans le style sublime est le plus efficace.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il épuise l’auditoire : le grand orateur alterne les trois styles.', 6),
    ('0ccdb52b-2b96-5e99-82a2-b4218dcc0b7a'::uuid, '3c7d74cc-cacf-5dc7-b8b2-faceafc1cf8c'::uuid, 'Qu’est-ce qu’un oxymore ?', 'mcq', '["Le rapprochement de deux termes contradictoires","La répétition d’un mot en début de phrase","Une comparaison développée","Un adoucissement du propos"]'::jsonb, 0, 'Il appartient aux figures d’opposition, avec l’antithèse et le chiasme.', 7),
    ('bbc6b1fa-8772-528c-a6c7-e5cf8a2611d0'::uuid, '3c7d74cc-cacf-5dc7-b8b2-faceafc1cf8c'::uuid, 'Le débat télévisé relève des mêmes mécanismes rhétoriques que le plaidoyer antique.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'La forme change, la structure de la persuasion reste.', 8),
    ('52e7555d-0d44-5f58-97eb-56d29ac71ddb'::uuid, '61795836-2c2b-5fd1-a27c-34f7fcdbd1de'::uuid, 'Quelle contrainte les réseaux sociaux imposent-ils à la parole publique ?', 'mcq', '["La brièveté et la recherche de la formule frappante","La rigueur argumentative","La longueur du développement","Le respect des cinq parties de la rhétorique"]'::jsonb, 0, 'Quelques secondes pour capter l’attention.', 1),
    ('3e2ad0d9-cf5b-56cd-a922-1a8271633e6a'::uuid, '61795836-2c2b-5fd1-a27c-34f7fcdbd1de'::uuid, 'Qu’est-ce que le storytelling en rhétorique contemporaine ?', 'mcq', '["Le remplacement de l’argument par un récit incarné","Une figure d’opposition","Un genre judiciaire","Un type de sondage"]'::jsonb, 0, 'Plus mémorable, et plus difficile à réfuter qu’un argument.', 2),
    ('d9c7ad43-46f4-576a-85d6-5be009341d35'::uuid, '61795836-2c2b-5fd1-a27c-34f7fcdbd1de'::uuid, 'Les ressorts de la rhétorique antique ont disparu des médias contemporains.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Ethos, pathos et logos y sont toujours à l’œuvre : ce sont les supports qui ont changé.', 3),
    ('c896fa3f-7b22-5213-90f6-2f6044ce253d'::uuid, '61795836-2c2b-5fd1-a27c-34f7fcdbd1de'::uuid, 'Que favorise la visibilité algorithmique ?', 'mcq', '["Les contenus qui suscitent le plus de réactions","Les contenus les mieux argumentés","Les contenus les plus longs","Les contenus les plus anciens"]'::jsonb, 0, 'D’où une prime à l’indignation et à la polémique.', 4),
    ('fdd5883c-ba11-5ce9-82ed-ad544647a011'::uuid, '61795836-2c2b-5fd1-a27c-34f7fcdbd1de'::uuid, 'Pourquoi une fausse information circule-t-elle souvent plus vite qu’un démenti ?', 'mcq', '["Parce qu’elle est conçue pour l’émotion, plus contagieuse que l’argument","Parce qu’elle est plus longue","Parce qu’elle vient de sources officielles","Parce qu’elle est mieux écrite"]'::jsonb, 0, 'Le démenti argumenté arrive après, et circule moins.', 5),
    ('6765d024-cf16-59fa-b840-deaa3bd19555'::uuid, '61795836-2c2b-5fd1-a27c-34f7fcdbd1de'::uuid, 'Qu’est-ce qu’un élément de langage ?', 'mcq', '["Une formule préparée et répétée jusqu’à s’imposer comme une évidence","Une figure de style antique","Un mot rare","Un terme technique"]'::jsonb, 0, 'Proche du slogan dans son fonctionnement.', 6),
    ('ebb6e2d5-b1e0-5a2c-9399-d3f3546c0331'::uuid, '61795836-2c2b-5fd1-a27c-34f7fcdbd1de'::uuid, 'Quel ressort aristotélicien est le parent pauvre de la communication contemporaine ?', 'mcq', '["Le logos","L’ethos","Le pathos","Aucun"]'::jsonb, 0, 'Le raisonnement cède le pas à l’image de soi et à l’émotion.', 7),
    ('c41c78c3-a8db-598e-83d3-e6de7f155988'::uuid, '61795836-2c2b-5fd1-a27c-34f7fcdbd1de'::uuid, 'Analyser un discours est aujourd’hui une compétence de défense autant que d’attaque.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est ce qui permet de ne pas être parlé par ce qu’on écoute.', 8),
    ('ea03de65-02ec-5e7e-aa07-b9ca7b84f8da'::uuid, '2610300c-0546-5a66-87ec-26997e15b8d3'::uuid, 'Qu’est-ce qui caractérise un mythe ?', 'mcq', '["Un récit anonyme et collectif qui explique une origine et fonde un ordre","Un récit d’auteur avec une morale explicite","Un récit historique vérifiable","Un récit destiné aux enfants"]'::jsonb, 0, 'Son autorité tient à ce qu’il est reçu et répété, non prouvé.', 1),
    ('c1a4c185-6691-5e85-b670-84d13f2e2220'::uuid, '2610300c-0546-5a66-87ec-26997e15b8d3'::uuid, 'Qu’est-ce qui distingue le mythe de la fable ?', 'mcq', '["La fable vise une leçon morale explicite","La fable est plus ancienne","La fable est collective et anonyme","La fable explique une origine"]'::jsonb, 0, 'Le mythe fonde, la fable enseigne.', 2),
    ('e38403d2-4392-5210-99c3-de12fe5e4160'::uuid, '2610300c-0546-5a66-87ec-26997e15b8d3'::uuid, 'Un mythe se démontre par des preuves.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il se raconte : c’est sa force et son danger.', 3),
    ('f929b84d-3d98-574a-a939-337b269da232'::uuid, '2610300c-0546-5a66-87ec-26997e15b8d3'::uuid, 'Quelle est la fonction fondatrice du mythe ?', 'mcq', '["Faire d’un groupe un « nous » par un récit d’origine partagé","Distraire l’auditoire","Établir des faits historiques","Enseigner une technique"]'::jsonb, 0, 'Rome a Romulus, Athènes la dispute d’Athéna et de Poséidon.', 4),
    ('af26f9b5-d7bb-5c05-ae5d-36a2f78ad995'::uuid, '2610300c-0546-5a66-87ec-26997e15b8d3'::uuid, 'Que signifie l’opposition entre muthos et logos chez Platon ?', 'mcq', '["Entre le récit reçu et le discours qui rend raison","Entre le vrai et le faux","Entre l’écrit et l’oral","Entre le grec et le latin"]'::jsonb, 0, 'Platon recourt pourtant lui-même au mythe quand l’argument ne suffit plus.', 5),
    ('02173346-93ff-51e4-b2d4-513222ee09a8'::uuid, '2610300c-0546-5a66-87ec-26997e15b8d3'::uuid, 'Platon rejette totalement le recours au mythe.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'La caverne, l’attelage ailé, le mythe d’Er : il y recourt quand l’argument s’arrête.', 6),
    ('2e726caf-bbe9-5538-9187-c4c321d29111'::uuid, '2610300c-0546-5a66-87ec-26997e15b8d3'::uuid, 'Que montre Barthes dans Mythologies ?', 'mcq', '["Que le mythe transforme aujourd’hui des constructions historiques en évidences naturelles","Que les mythes antiques sont faux","Que le mythe a disparu de la modernité","Que la publicité ignore le mythe"]'::jsonb, 0, 'Publicité, sport et politique en sont les nouveaux lieux.', 7),
    ('82b0d558-cb1a-566f-9f5d-ef4099e51121'::uuid, '2610300c-0546-5a66-87ec-26997e15b8d3'::uuid, 'Un récit d’origine peut légitimer une domination sans qu’on puisse le réfuter.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est le danger propre à une parole qui ne se discute pas.', 8),
    ('634fa6a4-9c48-5a4a-9fbc-9be78b85d21d'::uuid, 'f85a5e21-1abc-574c-9616-8e64b7340877'::uuid, 'Quelle autorité repose sur l’exemplarité de celui qui parle ?', 'mcq', '["L’autorité morale","L’autorité institutionnelle","L’autorité de compétence","L’autorité charismatique"]'::jsonb, 0, 'Sa vie garantit sa parole — et la démentir la lui fait perdre.', 1),
    ('b6bbc1d0-e20a-5738-af13-7e3f57024d4c'::uuid, 'f85a5e21-1abc-574c-9616-8e64b7340877'::uuid, 'Qu’est-ce qu’un énoncé performatif selon Austin ?', 'mcq', '["Un énoncé qui accomplit ce qu’il dit en le disant","Un énoncé particulièrement convaincant","Un énoncé qui décrit un fait","Un énoncé poétique"]'::jsonb, 0, 'Le verdict, le serment, la promesse en sont des exemples.', 2),
    ('aa3007ac-00c1-5d05-af32-784a27d7ec03'::uuid, 'f85a5e21-1abc-574c-9616-8e64b7340877'::uuid, 'Un performatif est efficace quel que soit celui qui le prononce.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il exige un cadre institutionnel : « je vous déclare unis » ne marie pas si un passant le dit.', 3),
    ('e37b1356-ae47-53df-8c7b-d402d4b56a45'::uuid, 'f85a5e21-1abc-574c-9616-8e64b7340877'::uuid, 'Pourquoi la mort de Socrate authentifie-t-elle sa parole ?', 'mcq', '["Parce qu’il accepte de mourir plutôt que de renier ce qu’il a dit","Parce qu’il a écrit une œuvre","Parce qu’il détenait une fonction officielle","Parce qu’il était le plus savant"]'::jsonb, 0, 'Sa conduite garantit son propos : c’est l’autorité morale à l’état pur.', 4),
    ('7e1892c4-67aa-54cc-b827-9e9399cdb772'::uuid, 'f85a5e21-1abc-574c-9616-8e64b7340877'::uuid, 'Qu’est-ce que l’argument d’autorité ?', 'mcq', '["Invoquer la position de celui qui parle au lieu d’examiner ce qu’il dit","Citer une source fiable","Employer un ton assuré","Parler au nom d’un groupe"]'::jsonb, 0, 'C’est un sophisme, à distinguer de la confiance raisonnée en un spécialiste.', 5),
    ('deed1d17-7017-5758-9e79-c2f5fd340763'::uuid, 'f85a5e21-1abc-574c-9616-8e64b7340877'::uuid, 'L’autorité institutionnelle dépend des qualités personnelles de celui qui l’exerce.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle vient de la FONCTION : c’est l’autorité morale qui se perd par la conduite.', 6),
    ('06aca54c-e0e4-5bb4-af38-89a027a53ec2'::uuid, 'f85a5e21-1abc-574c-9616-8e64b7340877'::uuid, 'Qui a analysé l’autorité charismatique ?', 'mcq', '["Max Weber","John Austin","Roland Barthes","Platon"]'::jsonb, 0, 'Il en souligne la puissance et l’instabilité.', 7),
    ('fd9bfe12-6f49-5fa3-a8c0-128b3f426ce0'::uuid, 'f85a5e21-1abc-574c-9616-8e64b7340877'::uuid, 'Faire confiance à un spécialiste est toujours un sophisme.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'On ne peut pas tout vérifier : la confiance raisonnée se distingue de la soumission.', 8),
    ('d209944b-3403-5b03-a0e5-4af0b31662ee'::uuid, 'b63d6e19-98eb-526f-8629-24bbd719ced7'::uuid, 'Que prétendaient enseigner les sophistes ?', 'mcq', '["L’art de faire triompher n’importe quelle cause par le discours","La science de la nature","La grammaire grecque","La géométrie"]'::jsonb, 0, 'Rendre « le discours le plus faible le plus fort » : ce que Platon leur reproche.', 1),
    ('fa24fa22-2d25-51ec-8bcf-d1c124152c28'::uuid, 'b63d6e19-98eb-526f-8629-24bbd719ced7'::uuid, 'Qu’est-ce que la parrhêsia ?', 'mcq', '["Le franc-parler : dire la vérité même à qui peut vous nuire","L’art de flatter le puissant","Le silence imposé","Une figure de style"]'::jsonb, 0, 'Foucault en fait une figure centrale du rapport entre vérité et pouvoir.', 2),
    ('2c98fa92-5778-5ab2-8ea7-ff225617558a'::uuid, 'b63d6e19-98eb-526f-8629-24bbd719ced7'::uuid, 'Interrompre et monopoliser le temps de parole sont des gestes de pouvoir.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Prendre, garder et refuser la parole dessinent une hiérarchie.', 3),
    ('e3396046-1e4a-52aa-81d4-0ba3d122776f'::uuid, 'b63d6e19-98eb-526f-8629-24bbd719ced7'::uuid, 'Qu’a montré Klemperer dans LTI ?', 'mcq', '["Comment un régime transforme la langue pour transformer les esprits","Comment traduire le latin","Comment enseigner la rhétorique","Comment se construit un mythe"]'::jsonb, 0, 'Le combat politique est aussi un combat sur les mots.', 4),
    ('af13f0ed-defb-5295-b3a8-cf1075bfdc68'::uuid, 'b63d6e19-98eb-526f-8629-24bbd719ced7'::uuid, 'Nommer une réalité est un acte neutre.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Nommer classe et hiérarchise : « émeute » ou « soulèvement » ne disent pas la même chose.', 5),
    ('54e33fc7-7f40-54d5-b3d2-657ca6eb5651'::uuid, 'b63d6e19-98eb-526f-8629-24bbd719ced7'::uuid, 'Pourquoi l’histoire des dominés est-elle d’abord celle d’un droit de parole ?', 'mcq', '["Parce que prendre la parole quand elle est refusée est déjà un acte politique","Parce qu’ils parlaient une autre langue","Parce qu’ils ne savaient pas écrire","Parce que la parole était sans importance"]'::jsonb, 0, 'L’acte compte avant même le contenu de ce qui est dit.', 6),
    ('868585ad-5ee8-5fb2-bf10-aacda658ad85'::uuid, 'b63d6e19-98eb-526f-8629-24bbd719ced7'::uuid, 'À Rome, quelle voie la carrière politique empruntait-elle principalement ?', 'mcq', '["Le barreau et la tribune","L’armée seule","Le commerce","La prêtrise"]'::jsonb, 0, 'Cicéron doit tout à son éloquence.', 7),
    ('0b226d34-de7f-5238-a190-cbe85fa978b9'::uuid, 'b63d6e19-98eb-526f-8629-24bbd719ced7'::uuid, 'La censure est la forme la plus brutale du pouvoir sur la parole.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Imposer le silence est aussi la plus révélatrice des rapports de force.', 8),
    ('abf14bde-537f-5de2-842a-64ae8dd47dca'::uuid, 'a1da650c-e853-5fce-94d3-62ee6f0322b5'::uuid, 'Que signifie l’enthousiasme, dans la tradition poétique grecque ?', 'mcq', '["Le fait d’avoir un dieu en soi, d’être inspiré","Une grande joie","Un travail acharné","Une technique apprise"]'::jsonb, 0, 'Les Muses parlent par la bouche du poète.', 1),
    ('01f337c2-60da-531e-bee1-084a0fc88701'::uuid, 'a1da650c-e853-5fce-94d3-62ee6f0322b5'::uuid, 'Que reproche Platon aux poètes dans la République ?', 'mcq', '["D’imiter les apparences et de flatter les passions","D’être trop savants","D’écrire en prose","De ne pas respecter le mètre"]'::jsonb, 0, 'Il les bannit de sa Cité idéale.', 2),
    ('77999a1c-1339-5b14-8e1d-bb44c8e2d1f0'::uuid, 'a1da650c-e853-5fce-94d3-62ee6f0322b5'::uuid, 'Selon Aristote, la poésie est plus philosophique que l’histoire.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Parce qu’elle dit le général là où l’histoire dit le particulier.', 3),
    ('456c1fb1-c282-5532-a543-beab7a1a29b9'::uuid, 'a1da650c-e853-5fce-94d3-62ee6f0322b5'::uuid, 'Que représente la figure d’Orphée ?', 'mcq', '["La puissance de la parole poétique sur le monde","La rigueur du raisonnement","L’autorité politique","La modestie du poète"]'::jsonb, 0, 'Son chant suspend les fleuves et arrache une morte aux Enfers.', 4),
    ('85fb2c4f-949e-5086-9223-aa99b1c4bbca'::uuid, 'a1da650c-e853-5fce-94d3-62ee6f0322b5'::uuid, 'Quel effet produit l’écart entre la langue poétique et la langue ordinaire ?', 'mcq', '["Il oblige à ralentir : le poème résiste et se relit","Il rend le poème plus clair","Il accélère la lecture","Il supprime toute ambiguïté"]'::jsonb, 0, 'Cette résistance fait la valeur du texte.', 5),
    ('38befe6d-f5c5-5e58-917d-0a32391a5197'::uuid, 'a1da650c-e853-5fce-94d3-62ee6f0322b5'::uuid, 'Dans l’Ion, Platon montre que le poète peut rendre compte de son savoir.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il montre l’inverse : ne sachant d’où vient ce qu’il dit, il n’en peut répondre.', 6),
    ('edea546b-2e99-5853-8d8c-8d53dda4a7ac'::uuid, 'a1da650c-e853-5fce-94d3-62ee6f0322b5'::uuid, 'Qu’ont en commun Baudelaire, Rimbaud et Mallarmé ?', 'mcq', '["Ils rompent avec la belle langue et explorent la matière du langage","Ils écrivent des épopées","Ils défendent la poésie didactique","Ils reviennent aux formes antiques"]'::jsonb, 0, 'Le poète devient explorateur du langage et figure marginale.', 7),
    ('3bdf2d27-0748-53f5-9815-a870ce90f033'::uuid, 'a1da650c-e853-5fce-94d3-62ee6f0322b5'::uuid, 'Que symbolise l’albatros de Baudelaire ?', 'mcq', '["Le poète, majestueux en son élément et empêché parmi les hommes","La liberté absolue","La puissance politique","La pureté de la langue"]'::jsonb, 0, 'Ses ailes de géant l’empêchent de marcher.', 8),
    ('92d90d4a-5fef-5d71-8de0-ee06490556ee'::uuid, '01ae4a9c-0084-5cf6-a67f-e63155ce15b7'::uuid, 'Qu’est-ce que l’amour courtois médiéval ?', 'mcq', '["Un code où le poète sert une dame inaccessible et où l’obstacle nourrit le désir","Un mariage arrangé","Une déclaration spontanée","Un genre théâtral"]'::jsonb, 0, 'Le désir s’y entretient de la distance.', 1),
    ('f129b611-9290-59c1-b9c6-8951aeff0c65'::uuid, '01ae4a9c-0084-5cf6-a67f-e63155ce15b7'::uuid, 'Qu’est-ce que le pétrarquisme ?', 'mcq', '["Un ensemble d’images convenues pour dire l’amour à la Renaissance","Une école philosophique","Une forme de sonnet uniquement","Un traité de rhétorique"]'::jsonb, 0, 'Feu et glace, doux supplice : Du Bellay et Shakespeare finiront par les moquer.', 2),
    ('7ed1df72-3e51-5476-892c-f0867e66b694'::uuid, '01ae4a9c-0084-5cf6-a67f-e63155ce15b7'::uuid, 'Selon La Rochefoucauld, la littérature amoureuse façonne le sentiment lui-même.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Bien des gens n’auraient jamais aimé s’ils n’en avaient entendu parler.', 3),
    ('3cf80e01-9f46-5a66-9f88-e1042aa7f339'::uuid, '01ae4a9c-0084-5cf6-a67f-e63155ce15b7'::uuid, 'Pourquoi le personnage de Dom Juan inquiète-t-il ?', 'mcq', '["Parce qu’il montre que le discours amoureux peut fonctionner à vide","Parce qu’il est trop sincère","Parce qu’il refuse de parler","Parce qu’il écrit des lettres"]'::jsonb, 0, 'Sa force est dans ce qu’il sait dire, non dans ce qu’il ressent.', 4),
    ('93f626f5-76f5-5505-9464-7db26a5b5efb'::uuid, '01ae4a9c-0084-5cf6-a67f-e63155ce15b7'::uuid, 'À quoi se heurte le discours amoureux, selon les auteurs du chapitre ?', 'mcq', '["À l’usure des mots, partagés par tous et incapables de dire l’unique","À l’interdiction sociale","À la brièveté du sentiment","À l’absence de vocabulaire"]'::jsonb, 0, 'D’où l’hyperbole, le néologisme, ou le silence.', 5),
    ('0af6386b-867f-5a36-bb8c-02e9f2d27869'::uuid, '01ae4a9c-0084-5cf6-a67f-e63155ce15b7'::uuid, 'Que décrit Barthes dans les Fragments d’un discours amoureux ?', 'mcq', '["Un amoureux qui parle seul et reprend pourtant les figures de tous ses prédécesseurs","Une histoire de l’amour courtois","Un manuel de séduction","Une critique du mariage"]'::jsonb, 0, 'La langue la plus intime est aussi la plus héritée.', 6),
    ('13e2b537-76fe-5744-998a-704e53280b74'::uuid, '01ae4a9c-0084-5cf6-a67f-e63155ce15b7'::uuid, 'La carte de Tendre représente les étapes du sentiment comme un itinéraire.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le XVIIe siècle cartographie ainsi la naissance de l’inclination.', 7),
    ('3da33120-aa47-54a2-bdaf-9a9141feed2a'::uuid, '01ae4a9c-0084-5cf6-a67f-e63155ce15b7'::uuid, 'Que fait la lettre d’amour, chez Rousseau ou Laclos ?', 'mcq', '["Elle donne une forme à l’absence, et creuse le manque autant qu’elle le comble","Elle remplace la rencontre","Elle supprime l’obstacle","Elle abolit les codes"]'::jsonb, 0, 'On écrit parce qu’on ne peut pas dire.', 8),
    ('de0ec0ad-0020-5e43-b9ea-0bd210fa2163'::uuid, '34a21f7d-5e8c-539c-86e6-b5c088a28a4e'::uuid, 'Pourquoi Kant juge-t-il le mensonge toujours interdit ?', 'mcq', '["Parce qu’il ruine la condition même du langage et traite autrui comme un moyen","Parce qu’il est inefficace","Parce qu’il est puni par la loi","Parce qu’il finit toujours par se savoir"]'::jsonb, 0, 'Il maintient l’interdit jusque dans le cas du meurtrier à la porte.', 1),
    ('d0085afb-60c1-50bb-89bd-91c4d4e7d5df'::uuid, '34a21f7d-5e8c-539c-86e6-b5c088a28a4e'::uuid, 'Que répond Benjamin Constant à Kant ?', 'mcq', '["Dire la vérité n’est un devoir qu’envers celui qui y a droit","Le mensonge est toujours permis","La vérité est inaccessible","Le silence vaut mieux que la parole"]'::jsonb, 0, 'Le meurtrier qui cherche sa victime n’a pas droit à la vérité.', 2),
    ('0774d8c2-eec5-515b-a437-fdcd778cc1cd'::uuid, '34a21f7d-5e8c-539c-86e6-b5c088a28a4e'::uuid, 'Une rumeur se répand parce qu’elle a été vérifiée.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle se répand parce qu’elle circule : chacun la croit vérifiée par le fait qu’un autre l’a dite.', 3),
    ('1a975705-f78e-5652-8e98-480492937633'::uuid, '34a21f7d-5e8c-539c-86e6-b5c088a28a4e'::uuid, 'Qu’est-ce qui rend la calomnie particulièrement grave ?', 'mcq', '["Son irréversibilité : un démenti n’efface pas ce qui a été entendu","Sa lenteur de propagation","Son caractère écrit","Sa légalité"]'::jsonb, 0, 'Le mal est fait avant que la vérité arrive.', 4),
    ('200fbb22-204f-597f-95fc-5b1f8af5faf5'::uuid, '34a21f7d-5e8c-539c-86e6-b5c088a28a4e'::uuid, 'Le silence est toujours l’absence de parole.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il en est une forme : prudence, complicité, respect ou censure.', 5),
    ('3786c2aa-4e1a-5fbb-a4da-2cd1e09ce8b2'::uuid, '34a21f7d-5e8c-539c-86e6-b5c088a28a4e'::uuid, 'Que désigne le kairos grec ?', 'mcq', '["Le moment opportun pour parler","Le franc-parler","La beauté du style","L’autorité de l’orateur"]'::jsonb, 0, 'Parler à propos fait partie de la parole juste.', 6),
    ('4c582ebe-2a07-5ca9-8c86-1cfae89a64e3'::uuid, '34a21f7d-5e8c-539c-86e6-b5c088a28a4e'::uuid, 'Quel silence relève de la complicité ?', 'mcq', '["Celui qui laisse faire ce qu’on désapprouve","Celui qui respecte la douleur","Celui qui retient une parole blessante","Celui qu’impose le censeur"]'::jsonb, 0, '« Qui ne dit mot consent. »', 7),
    ('a7f2a16d-ac0b-5bc3-b244-b3a6dbdb6ca5'::uuid, '34a21f7d-5e8c-539c-86e6-b5c088a28a4e'::uuid, 'Le droit de dire équivaut au devoir de tout dire.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Mesurer la portée de sa parole fait partie de son bon usage.', 8),
    ('37b20b87-5efa-5ada-a2d9-e63f5b335ca2'::uuid, '6c4d8fbe-1073-5d3c-99e0-f04889db9c31'::uuid, 'Pourquoi la « découverte » de l’Amérique doit-elle être étudiée sous un double aspect ?', 'mcq', '["Parce qu’elle est aussi une conquête et une destruction","Parce que Colomb s’est trompé de route","Parce qu’elle fut tardive","Parce qu’elle a enrichi l’Europe"]'::jsonb, 0, 'Effondrement démographique, évangélisation forcée et traite l’accompagnent.', 1),
    ('32e7f9a9-2d8d-5bb4-b406-f81550554195'::uuid, '6c4d8fbe-1073-5d3c-99e0-f04889db9c31'::uuid, 'Quelle attitude consiste à voir dans l’autre l’innocence perdue de l’Europe ?', 'mcq', '["L’idéalisation, avec la figure du bon sauvage","La réduction à la barbarie","La compréhension ethnographique","L’indifférence"]'::jsonb, 0, 'Le renversement est généreux, mais on parle encore de soi.', 2),
    ('ba014832-3681-5e62-888a-b86235c53387'::uuid, '6c4d8fbe-1073-5d3c-99e0-f04889db9c31'::uuid, 'Quel est l’enjeu de la controverse de Valladolid en 1550 ?', 'mcq', '["Savoir si les Indiens ont une âme et des droits","Le partage des terres conquises","La route des Indes","Le commerce des épices"]'::jsonb, 0, 'Que la question ait dû être posée en dit autant que la réponse.', 3),
    ('d8e663d2-c139-5ec2-ab9f-ea32e6d72d6c'::uuid, '6c4d8fbe-1073-5d3c-99e0-f04889db9c31'::uuid, 'Qui plaide pour la pleine humanité des Indiens à Valladolid ?', 'mcq', '["Las Casas","Sepúlveda","Montaigne","Colomb"]'::jsonb, 0, 'Sepúlveda défend, lui, la guerre juste et la servitude naturelle.', 4),
    ('5c772c08-7895-5093-ad20-fde8a0deeb51'::uuid, '6c4d8fbe-1073-5d3c-99e0-f04889db9c31'::uuid, 'Que soutient Montaigne dans « Des cannibales » ?', 'mcq', '["Que chacun appelle barbarie ce qui n’est pas de son usage","Que les cannibales doivent être civilisés","Que toutes les cultures se valent en tout point","Que l’Europe est supérieure"]'::jsonb, 0, 'Il compare la cruauté du cannibale à celle des guerres de religion.', 5),
    ('a1fcbb09-92ff-561e-9c14-82dbdb683838'::uuid, '6c4d8fbe-1073-5d3c-99e0-f04889db9c31'::uuid, 'Montaigne conclut que tous les usages se valent indifféremment.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il suspend le jugement le temps de regarder, et découvre que sa mesure était locale.', 6),
    ('aac467f7-c5b3-50a7-9e27-9a168f38e05d'::uuid, '6c4d8fbe-1073-5d3c-99e0-f04889db9c31'::uuid, 'Qu’est-ce que l’ethnocentrisme ?', 'mcq', '["Juger les autres cultures à l’aune de la sienne, tenue pour la mesure de toutes","L’étude scientifique des peuples","Le refus de voyager","La comparaison des langues"]'::jsonb, 0, 'Lévi-Strauss en fait l’attitude la mieux partagée du monde.', 7),
    ('52fb35ba-0991-5243-8ff9-9b8e752e8e76'::uuid, '6c4d8fbe-1073-5d3c-99e0-f04889db9c31'::uuid, 'Dans quel ouvrage Lévi-Strauss analyse-t-il l’ethnocentrisme ?', 'mcq', '["Race et histoire","Les Essais","Le Contrat social","Les Mythologies"]'::jsonb, 0, 'Chaque société tend à réserver le nom d’humanité à ses membres.', 8),
    ('d7889de2-d617-54b5-acde-df1330110f93'::uuid, 'e473a9ed-172d-57fd-9061-b0440109d1ef'::uuid, 'Que désigne le mot « barbare » chez les Grecs ?', 'mcq', '["Celui qui ne parle pas grec","Un ennemi militaire","Un être cruel","Un habitant du Nord"]'::jsonb, 0, 'La frontière est linguistique avant d’être morale.', 1),
    ('c2a936b8-ed71-583a-ac73-3438b7bf8020'::uuid, 'e473a9ed-172d-57fd-9061-b0440109d1ef'::uuid, 'Qu’a nommé Edward Said « orientalisme » ?', 'mcq', '["Le discours occidental qui construit un Orient rêvé et immobile","L’étude des langues orientales","Un courant pictural","Une religion"]'::jsonb, 0, 'Il en dit plus sur l’Occident que sur l’Orient.', 2),
    ('437fc8e6-5503-584d-b65f-659a51a6106e'::uuid, 'e473a9ed-172d-57fd-9061-b0440109d1ef'::uuid, 'Quel procédé Montesquieu emploie-t-il dans les Lettres persanes ?', 'mcq', '["Faire décrire la France par des étrangers pour la rendre étrange","Décrire la Perse avec exactitude","Comparer deux religions","Raconter un voyage réel"]'::jsonb, 0, '« Comment peut-on être Persan ? » retourne l’étonnement.', 3),
    ('ba654384-0a51-527c-81ac-5c913fc4b6d5'::uuid, 'e473a9ed-172d-57fd-9061-b0440109d1ef'::uuid, 'Comment appelle-t-on le fait de rendre étrange le familier pour le voir enfin ?', 'mcq', '["La défamiliarisation","L’ethnocentrisme","L’exotisme","L’allégorie"]'::jsonb, 0, 'C’est l’un des grands outils littéraires des Lumières.', 4),
    ('36de134a-440f-5aee-a393-5a87f8490c9b'::uuid, 'e473a9ed-172d-57fd-9061-b0440109d1ef'::uuid, 'Pourquoi les stéréotypes sont-ils si tenaces ?', 'mcq', '["Ils dispensent de connaître et se confirment eux-mêmes","Ils sont vérifiés par la science","Ils sont transmis par la loi","Ils sont rarement diffusés"]'::jsonb, 0, 'On remarque ce qui les vérifie et on oublie ce qui les dément.', 5),
    ('f309891f-2b89-52f1-bda6-c89c99d0f5ab'::uuid, 'e473a9ed-172d-57fd-9061-b0440109d1ef'::uuid, 'Les cartes médiévales peuplent les marges du monde de créatures monstrueuses.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'L’inconnu s’écrit d’abord en monstres.', 6),
    ('07e774c6-ae64-5d1a-a7fa-5fe56e88b60a'::uuid, 'e473a9ed-172d-57fd-9061-b0440109d1ef'::uuid, 'Que révèle une représentation de l’étranger ?', 'mcq', '["Autant celui qui la trace que celui qu’elle prétend décrire","Uniquement la culture décrite","Rien de significatif","La vérité historique"]'::jsonb, 0, 'Elle est toujours, aussi, un autoportrait.', 7),
    ('cdf0de8b-6ad2-5456-8efd-03039088eac8'::uuid, 'e473a9ed-172d-57fd-9061-b0440109d1ef'::uuid, 'Le regard naïf de L’Ingénu sert à démasquer l’arbitraire des usages français.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Voltaire emploie le même procédé que Montesquieu.', 8),
    ('67b6beef-1842-51bd-bfb9-d84a168e6cef'::uuid, '5c2f410c-6a44-5041-979a-d40c5e5ee68a'::uuid, 'Comment le cosmos d’Aristote et Ptolémée est-il conçu ?', 'mcq', '["Fini, clos et hiérarchisé, avec la Terre immobile au centre","Infini et homogène","Centré sur le Soleil","Sans ordre déterminé"]'::jsonb, 0, 'Le monde sublunaire y est celui du changement, le supralunaire celui de la perfection.', 1),
    ('268e60f2-61ab-5426-bda0-796f8d1513fd'::uuid, '5c2f410c-6a44-5041-979a-d40c5e5ee68a'::uuid, 'Qui a affirmé l’infinité de l’univers et la pluralité des mondes ?', 'mcq', '["Giordano Bruno","Copernic","Ptolémée","Newton"]'::jsonb, 0, 'Il est brûlé en 1600 pour cette thèse, entre autres.', 2),
    ('1a74f38a-4ab4-5762-98d2-82a77e920445'::uuid, '5c2f410c-6a44-5041-979a-d40c5e5ee68a'::uuid, 'Qu’observent les premières lunettes de Galilée ?', 'mcq', '["Les satellites de Jupiter et les reliefs de la Lune","Les anneaux de Saturne uniquement","Les galaxies lointaines","Le mouvement des comètes"]'::jsonb, 0, 'Tout ne tourne donc pas autour de la Terre, et le ciel n’est pas parfait.', 3),
    ('1e1c74a4-0b6c-5875-8474-184f158814b8'::uuid, '5c2f410c-6a44-5041-979a-d40c5e5ee68a'::uuid, 'Copernic place le Soleil au centre dès 1543.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'D’abord comme hypothèse de calcul, avant que d’autres en tirent les conséquences.', 4),
    ('30515103-ed48-592d-8830-f21604156183'::uuid, '5c2f410c-6a44-5041-979a-d40c5e5ee68a'::uuid, 'Quelle formule d’Alexandre Koyré résume la révolution astronomique ?', 'mcq', '["Du monde clos à l’univers infini","De la Terre au Soleil","Du mythe au logos","De la foi à la raison"]'::jsonb, 0, 'Elle donne son titre au chapitre.', 5),
    ('e1620c22-a073-58e4-af2f-59a6628912ed'::uuid, '5c2f410c-6a44-5041-979a-d40c5e5ee68a'::uuid, 'Que perd l’homme dans ce changement de cosmos ?', 'mcq', '["Sa position centrale et un univers ordonné par des places naturelles","Sa capacité de calcul","Son rapport à la religion uniquement","Rien d’essentiel"]'::jsonb, 0, 'L’univers n’a plus de haut ni de bas.', 6),
    ('87a52f9e-679a-5eb1-b5c9-632679f80177'::uuid, '5c2f410c-6a44-5041-979a-d40c5e5ee68a'::uuid, 'Quelle est la réponse de Pascal à l’effroi devant les espaces infinis ?', 'mcq', '["La pensée fait la grandeur de l’homme, qui sait ce qui l’écrase","Le retour au géocentrisme","Le refus de la science","L’indifférence"]'::jsonb, 0, 'L’univers écrase l’homme, mais il n’en sait rien.', 7),
    ('1cf34f19-f609-59ce-893c-e8f0020b5517'::uuid, '5c2f410c-6a44-5041-979a-d40c5e5ee68a'::uuid, 'Newton unifie le ciel et la terre sous une même loi.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'La gravitation universelle abolit la séparation entre sublunaire et supralunaire.', 8),
    ('292930a8-a95d-580a-9078-2d5ae82213e0'::uuid, '0e76ac95-9a0c-5479-90c7-861e318d9bc2'::uuid, 'D’où vient le mot « baroque » ?', 'mcq', '["De barroco, la perle irrégulière","Du nom d’un architecte","D’un mot grec signifiant excès","Du latin barbarus"]'::jsonb, 0, 'Le mot dit déjà l’irrégularité et l’instabilité.', 1),
    ('1d33ef38-f832-5efc-b42e-869929137ee9'::uuid, '0e76ac95-9a0c-5479-90c7-861e318d9bc2'::uuid, 'Quel trait N’EST PAS caractéristique du baroque ?', 'mcq', '["La symétrie apaisée","Le mouvement","L’illusion","La métamorphose"]'::jsonb, 0, 'La symétrie et la mesure sont du côté du classicisme.', 2),
    ('c4e195e3-d356-5797-83cc-1c4f5b468d09'::uuid, '0e76ac95-9a0c-5479-90c7-861e318d9bc2'::uuid, 'Que signifie le motif du theatrum mundi ?', 'mcq', '["Le monde est un théâtre où chacun joue un rôle qu’il n’a pas choisi","Le théâtre doit imiter le monde","Les acteurs sont des modèles","Le monde est un rêve sans réalité"]'::jsonb, 0, 'Shakespeare, Calderón et Corneille y reviennent.', 3),
    ('4b6bfd7b-4a20-5be0-8362-7854d1a34ebf'::uuid, '0e76ac95-9a0c-5479-90c7-861e318d9bc2'::uuid, 'Qu’est-ce qu’une vanité, en peinture baroque ?', 'mcq', '["Une composition rappelant la brièveté de la vie par des objets symboliques","Un portrait flatteur","Un paysage idéalisé","Une scène religieuse"]'::jsonb, 0, 'Crâne, sablier, fleur fanée, bulle de savon.', 4),
    ('de142393-b0ea-5464-ab86-370b982d4d8b'::uuid, '0e76ac95-9a0c-5479-90c7-861e318d9bc2'::uuid, 'L’instabilité baroque est un simple goût décoratif.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est une réponse esthétique à un monde qui a perdu ses repères.', 5),
    ('b81b612c-c9e6-5b5b-bd2d-1e6d845d0117'::uuid, '0e76ac95-9a0c-5479-90c7-861e318d9bc2'::uuid, 'Quel peintre est associé au clair-obscur violemment contrasté ?', 'mcq', '["Le Caravage","Poussin","Vermeer","Raphaël"]'::jsonb, 0, 'Le contraste ombre-lumière est un trait baroque majeur.', 6),
    ('0ad6fb06-d7c8-556b-b57b-d361511b3c02'::uuid, '0e76ac95-9a0c-5479-90c7-861e318d9bc2'::uuid, 'Que cherche le classicisme français, à l’inverse du baroque ?', 'mcq', '["La mesure, la symétrie, la clarté et le respect des règles","Le mouvement et l’excès","L’illusion et le trompe-l’œil","La métamorphose"]'::jsonb, 0, 'Les deux esthétiques coexistent pourtant, et se répondent.', 7),
    ('7a5934e3-3e22-5653-ab24-52030eea1ad3'::uuid, '0e76ac95-9a0c-5479-90c7-861e318d9bc2'::uuid, 'La vie est un songe, de Calderón, illustre le motif du monde comme théâtre.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le rôle, le déguisement et l’incertitude sur le réel y sont centraux.', 8),
    ('49ce8888-04a3-597a-9bc5-5dd3fc57d9fa'::uuid, 'a80c7001-fb13-528f-8516-32b01d2327d5'::uuid, 'Que signifie étymologiquement « encyclopédie » ?', 'mcq', '["Le cercle des connaissances","Le livre des sciences","La somme des livres","L’art de classer"]'::jsonb, 0, 'L’ambition est ancienne, mais change de nature au XVIIIe siècle.', 1),
    ('e5999519-4652-554c-8b9d-54f88d2ca8f9'::uuid, 'a80c7001-fb13-528f-8516-32b01d2327d5'::uuid, 'Quelle place l’Encyclopédie de Diderot donne-t-elle aux arts mécaniques ?', 'mcq', '["Une place considérable, avec onze volumes de planches","Une place marginale","Aucune place","Une place réservée aux annexes"]'::jsonb, 0, 'Les métiers et les techniques étaient jusque-là méprisés.', 2),
    ('09b8be38-39a1-5ce0-87ed-87ff5acb264b'::uuid, 'a80c7001-fb13-528f-8516-32b01d2327d5'::uuid, 'Sur quoi l’Encyclopédie fonde-t-elle la connaissance ?', 'mcq', '["Sur l’expérience et la raison, non sur l’autorité","Sur la révélation","Sur la tradition scolastique","Sur le consensus des savants"]'::jsonb, 0, 'C’est ce qui en fait une œuvre de combat.', 3),
    ('cc3d7695-ffb4-5cac-b1d9-6f4c03e9669b'::uuid, 'a80c7001-fb13-528f-8516-32b01d2327d5'::uuid, 'Comment les encyclopédistes déjouent-ils la censure ?', 'mcq', '["Par un système de renvois entre articles","En publiant à l’étranger uniquement","En signant sous pseudonyme","En supprimant les articles sensibles"]'::jsonb, 0, 'Un article anodin renvoie à un autre qui en ruine le contenu.', 4),
    ('a04d545e-3d35-5ac3-8d04-2807e0ca7b5c'::uuid, 'a80c7001-fb13-528f-8516-32b01d2327d5'::uuid, 'Selon quelles facultés l’arbre des connaissances range-t-il le savoir ?', 'mcq', '["Mémoire, raison et imagination","Théologie, droit et médecine","Nature, homme et Dieu","Passé, présent et avenir"]'::jsonb, 0, 'À quoi correspondent l’histoire, la philosophie et la poésie.', 5),
    ('1839d864-0200-5478-bd03-4083e52cc48e'::uuid, 'a80c7001-fb13-528f-8516-32b01d2327d5'::uuid, 'Classer le savoir est un geste neutre.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Classer, c’est déjà interpréter : le choix de l’ordre engage une conception du savoir.', 6),
    ('ce2de7f4-d03f-5a94-b6bb-04b8f186b6c1'::uuid, 'a80c7001-fb13-528f-8516-32b01d2327d5'::uuid, 'Quel avantage l’ordre alphabétique présente-t-il ?', 'mcq', '["Il rend l’ouvrage consultable par qui ne connaît pas encore les disciplines","Il respecte la hiérarchie des sciences","Il évite les renvois","Il regroupe les sujets voisins"]'::jsonb, 0, 'Il est arbitraire, mais neutre et accessible.', 7),
    ('79767bb3-8f66-5c19-afba-df453e36696d'::uuid, 'a80c7001-fb13-528f-8516-32b01d2327d5'::uuid, 'Toute encyclopédie comporte des angles morts.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Repérer ce qu’elle juge indigne d’un article fait partie de sa lecture.', 8),
    ('fcd3a42c-5b29-5f87-befa-3d27f515fb95'::uuid, '6bc589fe-ced9-5031-b508-d607ad6779b8'::uuid, 'Qui met au point la perspective linéaire au début du XVe siècle ?', 'mcq', '["Brunelleschi, à Florence","Alberti, à Rome","Léonard de Vinci, à Milan","Giotto, à Assise"]'::jsonb, 0, 'Alberti la théorise ensuite dans son traité de 1435.', 1),
    ('58b2982c-bc1e-545c-a589-05efb0300511'::uuid, '6bc589fe-ced9-5031-b508-d607ad6779b8'::uuid, 'Vers quoi convergent les lignes de fuite d’une perspective linéaire ?', 'mcq', '["Vers un point de fuite unique sur la ligne d’horizon","Vers les quatre coins du tableau","Vers le centre géométrique de la toile","Vers plusieurs points dispersés"]'::jsonb, 0, 'La taille des objets décroît avec l’éloignement.', 2),
    ('3e5190b6-aba1-59f4-95fd-9e679c889741'::uuid, '6bc589fe-ced9-5031-b508-d607ad6779b8'::uuid, 'De quoi dépendait la taille des figures dans l’art médiéval ?', 'mcq', '["De leur importance symbolique","De leur distance au spectateur","De la place disponible","De la richesse du commanditaire"]'::jsonb, 0, 'La perspective substitue la position à l’importance : un changement de logique complet.', 3),
    ('e2b60115-c63a-5778-b68a-f5e794fa5590'::uuid, '6bc589fe-ced9-5031-b508-d607ad6779b8'::uuid, 'Que soutient Panofsky à propos de la perspective ?', 'mcq', '["Qu’elle est une forme symbolique, convention historique et non vision vraie","Qu’elle est la seule représentation exacte","Qu’elle est un progrès technique sans conséquence","Qu’elle vient de l’Antiquité"]'::jsonb, 0, 'D’autres cultures ont représenté l’espace autrement, sans erreur ni retard.', 4),
    ('aa6c7f15-e915-51c2-9f9f-72ebb51156a9'::uuid, '6bc589fe-ced9-5031-b508-d607ad6779b8'::uuid, 'Qu’est-ce qu’une anamorphose ?', 'mcq', '["Une image déformée qui ne se recompose que vue d’un point oblique","Une peinture sans perspective","Un portrait de groupe","Une esquisse préparatoire"]'::jsonb, 0, 'Le crâne des Ambassadeurs de Holbein en est l’exemple canonique.', 5),
    ('f1e247d4-6142-55a2-ad1c-4ef8e9c8a43e'::uuid, '6bc589fe-ced9-5031-b508-d607ad6779b8'::uuid, 'La perspective suppose un spectateur placé en un point précis.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Elle institue un point de vue : le monde s’organise depuis un regard.', 6),
    ('95ebf534-c9f8-5d76-83ee-9439b5dc6f54'::uuid, '6bc589fe-ced9-5031-b508-d607ad6779b8'::uuid, 'Qu’apporte le cubisme à la question de la représentation de l’espace ?', 'mcq', '["Plusieurs points de vue coexistent sur la même toile","Un point de fuite plus précis","Le retour à l’art médiéval","La suppression de la couleur"]'::jsonb, 0, 'Un objet ne se donne jamais d’un seul coup.', 7),
    ('a5fdca16-acda-5eb9-ab94-845a70948903'::uuid, '6bc589fe-ced9-5031-b508-d607ad6779b8'::uuid, 'Représenter, c’est enregistrer fidèlement ce qui est.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Toute représentation construit, choisit un point de vue et en exclut d’autres.', 8),
    ('b93c2635-59a0-5633-8e7d-5303d4935551'::uuid, '85b49eaa-099e-5b0f-acbc-a5e05157ec57'::uuid, 'Qui appelle l’imagination « la folle du logis » ?', 'mcq', '["Malebranche","Pascal","Descartes","Kant"]'::jsonb, 0, 'Pascal, lui, en fait « maîtresse d’erreur et de fausseté ».', 1),
    ('128e376f-f918-5021-abcc-84d901d5b085'::uuid, '85b49eaa-099e-5b0f-acbc-a5e05157ec57'::uuid, 'Pourquoi Pascal juge-t-il l’imagination d’autant plus dangereuse ?', 'mcq', '["Parce qu’elle est parfois juste, si bien qu’on ne peut s’en défier systématiquement","Parce qu’elle est toujours fausse","Parce qu’elle est rare","Parce qu’elle est propre aux artistes"]'::jsonb, 0, 'Une faculté toujours trompeuse serait facile à écarter.', 2),
    ('e866d0b6-94d3-5829-b5f1-1d3a4cf36fa5'::uuid, '85b49eaa-099e-5b0f-acbc-a5e05157ec57'::uuid, 'Quel rôle Kant assigne-t-il à l’imagination ?', 'mcq', '["Une faculté nécessaire à la connaissance, qui synthétise le divers des sensations","Une faculté à bannir","Une simple faculté artistique","Un obstacle à l’entendement"]'::jsonb, 0, 'Sans elle, aucune expérience unifiée ne serait possible.', 3),
    ('f698a58a-4545-5e17-8018-5ae51dd84576'::uuid, '85b49eaa-099e-5b0f-acbc-a5e05157ec57'::uuid, 'Qui nomme l’imagination « la reine des facultés » ?', 'mcq', '["Baudelaire","Descartes","Malebranche","Bachelard"]'::jsonb, 0, 'Le romantisme en fait la faculté suprême.', 4),
    ('6949d30e-f9f9-52c6-a119-8b6c6eb61961'::uuid, '85b49eaa-099e-5b0f-acbc-a5e05157ec57'::uuid, 'Que montre Bachelard à propos de l’imagination ?', 'mcq', '["Qu’elle déforme les images plutôt qu’elle ne les recopie, et que c’est là sa force","Qu’elle est une mémoire fidèle","Qu’elle est propre à l’enfance","Qu’elle disparaît avec le savoir"]'::jsonb, 0, 'L’imagination est dynamique, non reproductrice.', 5),
    ('cfccfa28-2983-5721-8fa0-ac2eadde6aea'::uuid, '85b49eaa-099e-5b0f-acbc-a5e05157ec57'::uuid, 'La démarche scientifique se passe d’imagination.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'L’hypothèse, l’expérience de pensée et le modèle en sont des actes.', 6),
    ('aa1ed99e-9ca0-54a7-8110-f610b68cda56'::uuid, '85b49eaa-099e-5b0f-acbc-a5e05157ec57'::uuid, 'Qu’est-ce qui distingue la science de la rêverie ?', 'mcq', '["La soumission de l’imaginé à l’épreuve des faits","L’absence totale d’imagination","L’usage du calcul","Le recours à des instruments"]'::jsonb, 0, 'Imaginer est le premier temps ; vérifier est obligatoire.', 7),
    ('1ccef84f-1b64-588b-91f6-846df8fa2481'::uuid, '85b49eaa-099e-5b0f-acbc-a5e05157ec57'::uuid, 'L’imagination joue un rôle dans le jugement moral.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Se représenter ce qu’éprouve autrui rend l’empathie possible.', 8),
    ('70daa303-afd6-5c28-98ab-520d0dce67da'::uuid, '6475e00e-b1e9-55b4-a194-9131f63d69fa'::uuid, 'Selon Aristote, qu’est-ce qui distingue l’homme de l’animal ?', 'mcq', '["Le logos, qui permet de dire le juste et l’injuste","La station debout","La force physique","La longévité"]'::jsonb, 0, 'L’animal exprime plaisir et douleur, il ne délibère pas.', 1),
    ('4890dac3-de77-5b5c-950c-4f8c007e5b88'::uuid, '6475e00e-b1e9-55b4-a194-9131f63d69fa'::uuid, 'Pourquoi Bergson préfère-t-il homo faber à homo sapiens ?', 'mcq', '["Parce que l’homme fabrique des outils à fabriquer des outils","Parce qu’il travaille la terre","Parce qu’il construit des maisons","Parce qu’il domestique les animaux"]'::jsonb, 0, 'C’est la technique récursive, non la simple intelligence, qui le caractérise.', 2),
    ('e6aa066e-95dd-5d9e-931a-6287cd887f38'::uuid, '6475e00e-b1e9-55b4-a194-9131f63d69fa'::uuid, 'Qu’a montré l’éthologie sur la fabrication d’outils ?', 'mcq', '["Plusieurs espèces animales en fabriquent et se les transmettent","Seuls les humains en fabriquent","Les animaux les utilisent sans les fabriquer","Les outils animaux sont innés"]'::jsonb, 0, 'Chimpanzés, corbeaux et loutres en fournissent des exemples.', 3),
    ('fef7b7fe-06de-58e9-833b-3bb9a5334e47'::uuid, '6475e00e-b1e9-55b4-a194-9131f63d69fa'::uuid, 'Quel est le critère décisif du propre de l’homme chez Descartes ?', 'mcq', '["Le langage, entendu comme réponse nouvelle à une situation nouvelle","La conscience de la mort","Le rire","La sociabilité"]'::jsonb, 0, 'Les animaux ne composent jamais un discours inédit, selon lui.', 4),
    ('633ceb7a-b6ea-5cc7-b204-02b798108976'::uuid, '6475e00e-b1e9-55b4-a194-9131f63d69fa'::uuid, 'La différence entre l’homme et l’animal est aujourd’hui pensée comme une différence de nature.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle est plus vraisemblablement de DEGRÉ, chaque critère absolu ayant reculé.', 5),
    ('0a8a2146-2165-5863-9093-bbe1b1288003'::uuid, '6475e00e-b1e9-55b4-a194-9131f63d69fa'::uuid, 'Qui range l’homme parmi les primates dès le XVIIIe siècle ?', 'mcq', '["Linné","Darwin","Buffon","Aristote"]'::jsonb, 0, 'Darwin l’inscrira ensuite dans une continuité évolutive.', 6),
    ('390039df-6c99-56e3-bbd7-34bed0dfdc5d'::uuid, '6475e00e-b1e9-55b4-a194-9131f63d69fa'::uuid, 'Plusieurs espèces humaines ont coexisté au cours de la préhistoire.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Homo sapiens est resté longtemps l’une d’elles.', 7),
    ('99a1ecb3-acb5-59bc-a95b-80d44894f897'::uuid, '6475e00e-b1e9-55b4-a194-9131f63d69fa'::uuid, 'Que reste-t-il du propre de l’homme selon le chapitre ?', 'mcq', '["Un faisceau de traits, dont la capacité de se poser la question elle-même","Un critère unique et définitif","Rien du tout","La seule supériorité physique"]'::jsonb, 0, 'Langage articulé, culture cumulative, mondes possibles.', 8),
    ('257a4f8d-a3f0-5d09-862d-dcbacd85ca68'::uuid, 'cdbd0410-3752-5e57-ab5c-c52fbc676307'::uuid, 'Que soutient Descartes avec la thèse de l’animal-machine ?', 'mcq', '["Les animaux sont des automates sans pensée ni sensibilité au sens propre","Les animaux pensent comme les hommes","Les animaux ont une âme immortelle","Les animaux communiquent par le langage"]'::jsonb, 0, 'La vivisection n’y pose alors aucun problème moral.', 1),
    ('c2760c4d-67f5-56d3-b503-a1f013d2b006'::uuid, 'cdbd0410-3752-5e57-ab5c-c52fbc676307'::uuid, 'Quelle question Bentham substitue-t-il à celle de la raison animale ?', 'mcq', '["Peuvent-ils souffrir ?","Peuvent-ils parler ?","Peuvent-ils travailler ?","Peuvent-ils apprendre ?"]'::jsonb, 0, 'Le critère moral devient la sensibilité, non l’intelligence.', 2),
    ('30a7d25e-fc10-5bac-a869-d91270c7efc7'::uuid, 'cdbd0410-3752-5e57-ab5c-c52fbc676307'::uuid, 'Comment Montaigne renverse-t-il la position de surplomb sur l’animal ?', 'mcq', '["En se demandant si sa chatte ne se joue pas de lui autant que lui d’elle","En affirmant la supériorité humaine","En comparant les langages","En décrivant des expériences"]'::jsonb, 0, 'Le doute porte sur le point de vue même de celui qui juge.', 3),
    ('d37f636d-37b9-5547-b308-2a7c7fdf8bfe'::uuid, 'cdbd0410-3752-5e57-ab5c-c52fbc676307'::uuid, 'Qu’est-ce que l’Umwelt selon von Uexküll ?', 'mcq', '["Le monde perçu propre à chaque espèce, structuré par ses organes et ses besoins","L’environnement physique commun à tous","Le territoire d’un animal","La niche écologique d’une espèce"]'::jsonb, 0, 'La tique n’habite pas un monde appauvri : un monde autrement fait.', 4),
    ('25dd1b89-aea1-5a4e-a8ac-36b50a5c42d1'::uuid, 'cdbd0410-3752-5e57-ab5c-c52fbc676307'::uuid, 'Depuis 2015, le code civil français reconnaît l’animal comme un être doué de sensibilité.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Tout en le soumettant encore au régime des biens : le compromis est parlant.', 5),
    ('d7fcb101-55d6-5913-aa7c-9b3ef244c294'::uuid, 'cdbd0410-3752-5e57-ab5c-c52fbc676307'::uuid, 'Qui consacre un Discours à Madame de la Sablière à réfuter l’animal-machine ?', 'mcq', '["La Fontaine","Montaigne","Voltaire","Rousseau"]'::jsonb, 0, 'Il y oppose les conduites animales observées à la thèse cartésienne.', 6),
    ('95fa45e3-fed8-5b9b-8eca-44ee3d9429f4'::uuid, 'cdbd0410-3752-5e57-ab5c-c52fbc676307'::uuid, 'Penser « l’animal » au singulier va de soi.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le mot recouvre l’éponge et le chimpanzé : le singulier est déjà une décision.', 7),
    ('c8b8e0ec-4ef7-5e70-9f22-655d3f93ce3e'::uuid, 'cdbd0410-3752-5e57-ab5c-c52fbc676307'::uuid, 'Qu’est-ce que le test du miroir met en évidence chez certaines espèces ?', 'mcq', '["Une forme de reconnaissance de soi","La vision des couleurs","La mémoire spatiale","La capacité de communiquer"]'::jsonb, 0, 'Il fait partie des observations qui ont fait reculer la thèse de l’automate.', 8),
    ('9c72516f-745e-533e-8b74-00c9b05d28e0'::uuid, '350c630d-b8fa-5b45-87af-38592f5e0246'::uuid, 'Que défend la position welfariste ?', 'mcq', '["Réduire la souffrance animale sans contester l’usage des animaux","Abolir tout usage des animaux","Accorder des droits identiques aux humains et aux animaux","Supprimer toute réglementation"]'::jsonb, 0, 'C’est la position dominante dans le droit européen.', 1),
    ('2279a922-8bcc-5565-bdc6-22f50a1f7906'::uuid, '350c630d-b8fa-5b45-87af-38592f5e0246'::uuid, 'Qu’est-ce que le spécisme selon Peter Singer ?', 'mcq', '["Le fait d’écarter un intérêt au seul motif qu’il est celui d’un animal","La classification des espèces","La protection des espèces menacées","L’élevage sélectif"]'::jsonb, 0, 'Il en fait une discrimination analogue, dans sa forme, au racisme.', 2),
    ('898f295e-d189-58cc-baa2-1d2fab17e78b'::uuid, '350c630d-b8fa-5b45-87af-38592f5e0246'::uuid, 'Sur quelle notion Tom Regan fonde-t-il sa position abolitionniste ?', 'mcq', '["Le sujet-d’une-vie, capable de préférences, qui ne peut être un moyen","Le contrat social","La réduction de la souffrance","La valeur économique"]'::jsonb, 0, 'Il raisonne en termes de droits, non de bien-être.', 3),
    ('6910bc23-bd09-5479-a67c-cf2a77608c56'::uuid, '350c630d-b8fa-5b45-87af-38592f5e0246'::uuid, 'Que recouvre la règle des trois R en expérimentation animale ?', 'mcq', '["Remplacer, réduire, raffiner","Recenser, réglementer, rapporter","Répertorier, restreindre, rétribuer","Reconnaître, respecter, réparer"]'::jsonb, 0, 'Elle encadre l’expérimentation sans l’interdire.', 4),
    ('a935d8f8-d1ae-5dfc-9025-326cb91ac078'::uuid, '350c630d-b8fa-5b45-87af-38592f5e0246'::uuid, 'Quelle objection les contractualistes opposent-ils aux droits des animaux ?', 'mcq', '["Les droits supposent des obligations réciproques, impossibles pour un animal","Les animaux ne souffrent pas","Les animaux ne sont pas nombreux","Le droit ne concerne que la propriété"]'::jsonb, 0, 'On y répond par le cas des jeunes enfants, titulaires de droits sans devoirs.', 5),
    ('36444bea-989e-55e3-91bc-05be5c13e1f0'::uuid, '350c630d-b8fa-5b45-87af-38592f5e0246'::uuid, 'L’élevage intensif pose des enjeux écologiques et sanitaires, en plus de la question animale.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Émissions, usage des terres, zoonoses et résistance aux antibiotiques.', 6),
    ('7cd22b2f-7e7f-56df-a484-b93b93d2447b'::uuid, '350c630d-b8fa-5b45-87af-38592f5e0246'::uuid, 'Le droit français est parfaitement cohérent sur le statut de l’animal.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il punit la cruauté tout en maintenant élevage, chasse et corrida sous conditions.', 7),
    ('02b124c2-0b79-579d-851d-b1f492babb48'::uuid, '350c630d-b8fa-5b45-87af-38592f5e0246'::uuid, 'Qu’attend un devoir de HLP sur cette question ?', 'mcq', '["Une argumentation identifiant le critère moral retenu et ses objections","Une opinion personnelle tranchée","Un exposé des seules données scientifiques","Un résumé du droit en vigueur"]'::jsonb, 0, 'Sensibilité, intérêt, droit ou réciprocité : le critère décide de tout.', 8)
  ) AS v(id, quiz_id, question, kind, options, correct_index, explanation, position)
-- Le quiz doit exister : si le NOT EXISTS ci-dessus a écarté un quiz (une
-- leçon en avait déjà un), ses questions ne partent pas dans le vide.
 WHERE EXISTS (SELECT 1 FROM public.quizzes qz WHERE qz.id = v.quiz_id)
ON CONFLICT (id) DO NOTHING;

-- 5. Sonde finale ----------------------------------------------------------
DO $$
DECLARE
  n_vides integer;
  n_chap  integer;
BEGIN
  SELECT count(*) INTO n_chap FROM public.chapters c
   JOIN public.subjects s ON s.id = c.subject_id
   WHERE s.slug IN ('hlp');
  SELECT count(*) INTO n_vides FROM public.subjects s
   WHERE s.slug IN ('hlp')
     AND NOT EXISTS (SELECT 1 FROM public.chapters c WHERE c.subject_id = s.id);
  IF n_vides > 0 THEN
    RAISE EXCEPTION 'Migration 274 incomplète : % matiere(s) encore sans chapitre', n_vides;
  END IF;
  RAISE NOTICE 'Migration 274 OK : % chapitres sur les matieres visees.', n_chap;
END $$;
